('84dad3b1-d223-41be-b669-33728751726f','cover-letter','Cover Letter','document',1240,1754,'[{"id":"p1","background":{"type":"solid","color":"#FFFFFF"},"elements":[{"id":"rect_mvv4693o10yvbgl9","type":"rect","x":0,"y":0,"width":1240,"height":200,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#1E3A5F","stroke":"transparent","strokeWidth":0,"cornerRadius":24},{"id":"text_mvv4693o10zuogv4","type":"text","x":90,"y":60,"width":700,"height":60,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"RACHEL OKONJO","fontSize":38,"fontFamily":"Playfair Display","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#FFFFFF","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o1107s4jw","type":"text","x":92,"y":125,"width":700,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Chief Operating Officer · New York, NY","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#BFD9EA","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o111dlw5s","type":"text","x":90,"y":260,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"March 4, 2026","fontSize":21,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#7A8CA0","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o112etucs","type":"text","x":90,"y":330,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Hiring Committee · Northbay Industrial","fontSize":22,"fontFamily":"Inter","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#172A40","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o113jaczg","type":"text","x":90,"y":375,"width":1060,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"300 Harbor Street, Boston, MA","fontSize":21,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#7A8CA0","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o114trvug","type":"text","x":90,"y":450,"width":1060,"height":60,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Dear Committee,","fontSize":32,"fontFamily":"Playfair Display","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#1E3A5F","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o115mszgn","type":"text","x":90,"y":540,"width":1060,"height":200,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Your posting describes a company doubling in size while trying not to double its complexity. That is the exact problem I have spent the last decade solving — most recently as COO of Meridian Logistics, where we grew from $38M to $121M with flat headcount.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3B4D61","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693o116pphws","type":"text","x":90,"y":760,"width":1060,"height":200,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"I noticed Northbay’s 10-K flags inventory turns as your top drag on margin. At Atlas Foods I led an S&OP rollout that freed $9.2M in working capital across four plants, and at Craft Retail I cut stockouts by 31% without adding a single planner. Operations should be boring in the best way — predictable, measured, quietly compounding.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3B4D61","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693o1171gi46","type":"text","x":90,"y":980,"width":1060,"height":200,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"What drew me to your posting specifically was the line about “building the company our grandmothers could work at.” Culture at scale is an operations problem too. At Meridian, our eNPS went from +11 to +48 while we integrated a $60M acquisition — not because of perks, but because we fixed the processes that made people’s weeks miserable.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3B4D61","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693o118cd7pr","type":"text","x":90,"y":1200,"width":1060,"height":200,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"I would welcome the chance to walk you through the routing-stack rebuild in detail — it maps closely to your distribution expansion, and I suspect parts of it would transfer. Thank you for your time and consideration.","fontSize":23,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3B4D61","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693o1196zcg3","type":"text","x":90,"y":1430,"width":1060,"height":60,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Warm regards,","fontSize":32,"fontFamily":"Playfair Display","bold":false,"italic":true,"underline":false,"strike":false,"uppercase":false,"fill":"#1E3A5F","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o11av20dr","type":"text","x":90,"y":1500,"width":1060,"height":55,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Rachel Okonjo","fontSize":52,"fontFamily":"Great Vibes","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#172A40","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"line_mvv4693o11bab0pn","type":"line","x":92,"y":1570,"width":320,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#D7E2EC","strokeWidth":2,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"text_mvv4693o11cefuz3","type":"text","x":90,"y":1590,"width":700,"height":45,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"rachel.okonjo@mail.com · +1 (555) 240-1188","fontSize":20,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#7A8CA0","align":"left","lineHeight":1.25,"letterSpacing":0}]}]'::jsonb,'#1E3A5F'),
('0efa032f-52c9-4920-8bd3-a852787835f1','project-proposal','Project Proposal','document',1240,1754,'[{"id":"p1","background":{"type":"solid","color":"#FFFFFF"},"elements":[{"id":"rect_mvv4693o11dgqt5w","type":"rect","x":0,"y":0,"width":1240,"height":330,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#F0FDFA","stroke":"transparent","strokeWidth":0,"cornerRadius":24},{"id":"text_mvv4693o11emj39t","type":"text","x":90,"y":70,"width":700,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"PROJECT PROPOSAL · #2026-014","fontSize":22,"fontFamily":"DM Mono","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#0F766E","align":"left","lineHeight":1.25,"letterSpacing":3},{"id":"text_mvv4693o11fqmwyr","type":"text","x":85,"y":125,"width":1000,"height":110,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Willow Park Playground Rebuild","fontSize":64,"fontFamily":"Outfit","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#134E4A","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o11gw70ty","type":"text","x":90,"y":250,"width":1000,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Prepared for the City of Willow Park · April 2026","fontSize":24,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#0F766E","align":"left","lineHeight":1.25,"letterSpacing":0},{"id":"text_mvv4693o11hqtjzr","type":"text","x":90,"y":390,"width":1060,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"1 · WHAT WE PROPOSE","fontSize":26,"fontFamily":"Outfit","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#134E4A","align":"left","lineHeight":1.25,"letterSpacing":2},{"id":"text_mvv4693o11idk2jo","type":"text","x":90,"y":450,"width":1060,"height":170,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"A full rebuild of the Willow Park playground on its existing footprint: inclusive surfacing, a fenced toddler zone, shade canopies over 60% of the play area, and a water-mist feature for summer months. The current structure is 24 years old and fails current safety standards in three areas.","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3F5450","align":"left","lineHeight":1.7,"letterSpacing":0},{"id":"text_mvv4693o11j41u7x","type":"text","x":90,"y":660,"width":1060,"height":50,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"2 · SCOPE OF WORK","fontSize":26,"fontFamily":"Outfit","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#134E4A","align":"left","lineHeight":1.25,"letterSpacing":2},{"id":"text_mvv4693p11km4wtn","type":"text","x":90,"y":715,"width":500,"height":300,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Demolition & site prep (2 weeks)\nNew play structure, ages 2–12 (3 weeks)\nPoured rubber surfacing, all-access (1 week)\nShade canopies + misting station (1 week)\nLandscaping & benches (1 week)","fontSize":22,"fontFamily":"Inter","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#3F5450","align":"left","lineHeight":1.9,"letterSpacing":0},{"id":"rect_mvv4693p11le7p8y","typ